"""Compute the GF(2) matrix rows for state_at(x, .) restricted to the low 24 bits,
given base_nonce (from the banner). rows[x] is a 64-bit int: bit j set means
seed bit j contributes to the low-24-bit output."""

MASK64 = (1 << 64) - 1


def _transform(state, num, shifts):
    if num % 2 == 0:
        state ^= (state << shifts[0]) & MASK64
        state ^= state >> shifts[1]
        state ^= (state << shifts[2]) & MASK64
        state ^= state >> shifts[3]
    else:
        state ^= state >> shifts[0]
        state ^= (state << shifts[1]) & MASK64
        state ^= state >> shifts[2]
        state ^= (state << shifts[3]) & MASK64
    return state & MASK64


def _transformation(operator, state):
    result = 0
    for bit in range(64):
        if state & (1 << bit):
            result ^= operator[bit]
    return result & MASK64


def _square_operator(operator):
    return [_transformation(operator, column) for column in operator]


def build_params(base_nonce):
    from hashlib import shake_256
    material = shake_256(base_nonce).digest(5)
    available_shifts = list(range(1, 64))
    shifts = []
    for byte in material[1:]:
        index = byte % len(available_shifts)
        shifts.append(available_shifts.pop(index))
    num = material[0] & 1
    return shifts, num


def build_rows(base_nonce):
    shifts, num = build_params(base_nonce)
    first_jump = [_transform(1 << bit, num, shifts) for bit in range(64)]
    jumps = [first_jump]
    for _ in range(63):
        jumps.append(_square_operator(jumps[-1]))

    def state_at(x, seed):
        state = seed & MASK64
        for bit in range(64):
            if x & (1 << bit):
                state = _transformation(jumps[bit], state)
        return state

    rows = {}
    for x in range(1, 200):
        row = 0
        for j in range(64):
            if state_at(x, 1 << j) & 1:
                row |= 1 << j
        rows[x] = row
    return rows

"""Build the GF(2) matrix for state_at(x, .) restricted to low 24 bits,
given base_nonce (recovered from the banner).

For each x, cols[x] = [c_0..c_63] (24-bit ints) such that
    out = state_at(x, seed) & 0xFFFFFF = XOR_{j: seed_j = 1} c_j
i.e. c_j = state_at(x, 1 << j) & 0xFFFFFF.
"""

MASK64 = (1 << 64) - 1


def _transform(state, num, shifts):
    if num % 2 == 0:
        state ^= (state << shifts[0]) & MASK64
        state ^= state >> shifts[1]
        state ^= (state << shifts[2]) & MASK64
        state ^= state >> shifts[3]
    else:
        state ^= state >> shifts[0]
        state ^= (state << shifts[1]) & MASK64
        state ^= state >> shifts[2]
        state ^= (state << shifts[3]) & MASK64
    return state & MASK64


def _transformation(operator, state):
    result = 0
    for bit in range(64):
        if state & (1 << bit):
            result ^= operator[bit]
    return result & MASK64


def _square_operator(operator):
    return [_transformation(operator, column) for column in operator]


def build_params(base_nonce):
    from hashlib import shake_256
    material = shake_256(base_nonce).digest(5)
    available_shifts = list(range(1, 64))
    shifts = []
    for byte in material[1:]:
        index = byte % len(available_shifts)
        shifts.append(available_shifts.pop(index))
    num = material[0] & 1
    return shifts, num


def build_cols(base_nonce, xs=range(1, 200)):
    shifts, num = build_params(base_nonce)
    first_jump = [_transform(1 << bit, num, shifts) for bit in range(64)]
    jumps = [first_jump]
    for _ in range(63):
        jumps.append(_square_operator(jumps[-1]))

    def state_at(x, seed):
        state = seed & MASK64
        for bit in range(64):
            if x & (1 << bit):
                state = _transformation(jumps[bit], state)
        return state

    cols = {}
    for x in xs:
        cols[x] = [state_at(x, 1 << j) & 0xFFFFFF for j in range(64)]
    return cols


def build_rows(base_nonce, xs=range(1, 200)):
    """Legacy helper: bit j of rows[x] = LSB of column j."""
    cols = build_cols(base_nonce, xs)
    return {x: sum(((c[0] >> 0) & 1) << j for j, c in enumerate(cc))
            for x, cc in cols.items()}

